exec(compile("\"\"\"GPU execution admission for authorized downstream neural models only.\n\nB0's CPU-only producer admission remains unchanged. This runtime uses the same\nUID quota and model reserve, checks actual node root/tmp capacity, and holds the\nexisting cross-window GPU UUID flock for its entire native process lifetime.\n\"\"\"\nimport ast\nimport csv\nimport fcntl\nimport json\nimport os\nfrom pathlib import Path\nimport socket\nimport subprocess\nimport time\nfrom workflows.benchmark_data.acquire import guard, quota_headroom\n\nGPU_NODES=frozenset(\"compute-0-\"+str(i) for i in range(8))|{\"compute-0-20\",\"compute-0-22\"}\nLOCK_ROOT=Path(\"/share/home/zixiao/descriptor_analysis/docs/phase1/evidence/stage46_shared_gpu_launch/.own_gpu_uuid_locks\")\nMODEL_RESERVE=114569896448\nGIB=1024**3\n\ndef gpu_admission(card, contexts, expected_uuid, minimum_free_mib=18432):\n    if card[\"uuid\"]!=expected_uuid:\n        raise RuntimeError(\"Actual GPU UUID differs from the scheduled card\")\n    used,total=float(card[\"used_mib\"]),float(card[\"total_mib\"])\n    if total<=0 or used<0 or used/total>.30 or total-used<minimum_free_mib:\n        raise RuntimeError(\"Actual free GPU memory does not cover the planned neural job\")\n    if float(card.get(\"utilization_percent\",0))>5:\n        raise RuntimeError(\"Actual GPU activity is not idle for this small-task launch\")\n    if any(row[\"gpu_uuid\"]==expected_uuid for row in contexts):\n        raise RuntimeError(\"An existing compute context owns this small-task GPU\")\n    return dict(card)\n\ndef root_capacity(stat, needed, same_root_filesystem=True):\n    total=stat.f_blocks*stat.f_frsize;available=stat.f_bavail*stat.f_frsize\n    reserve=max(10*GIB,.10*total) if same_root_filesystem else max(GIB,.10*total)\n    if available<reserve+needed or stat.f_favail<2000:\n        raise RuntimeError(\"Native root/tmp bytes or inodes would cross system/Slurm reserve\")\n    return dict(total_bytes=total,available_bytes=available,reserved_bytes=int(reserve),\n                future_local_bytes=needed,available_inodes=stat.f_favail)\n\ndef quota_observation(record, uid, now):\n    if (record.get(\"uid\")!=uid or record.get(\"generation\")!=\"benchmarkB020261119\" or\n            record.get(\"returncode\")!=0 or not 0<=now-record.get(\"observed_epoch\",-1)<=90):\n        raise RuntimeError(\"Missing/stale/mismatched native UID quota observation\")\n    return quota_headroom(record[\"raw\"],uid)\n\nclass GpuRuntime:\n    def __init__(self, root, snapshot, *, gpu_uuid, expected_node, learner, minimum_free_mib=18432):\n        if learner not in (\"Chemprop-v2\",\"TabPFN\"):raise ValueError(\"A neural GPU learner is required\")\n        self.root=Path(root);self.snapshot=Path(snapshot)\n        self.node=socket.gethostname().split(\".\")[0];self.job=os.environ.get(\"SLURM_JOB_ID\")\n        if self.node not in GPU_NODES or self.node!=expected_node or not self.job:\n            raise RuntimeError(\"A matching actual development GPU-node Slurm allocation is required\")\n        if int(os.environ.get(\"SLURM_CPUS_PER_TASK\",\"0\"))<1:\n            raise RuntimeError(\"Actual demand-based Slurm CPU allocation is required\")\n        self.gpu_uuid=gpu_uuid;self.learner=learner\n        self.protect(self.root,16*1024**2,self.snapshot,own_concurrent_bytes=40*GIB)\n        if not LOCK_ROOT.is_dir():\n            raise RuntimeError(\"The established cross-window GPU lock root is unavailable\")\n        self.lock=(LOCK_ROOT/(gpu_uuid+\".lock\")).open(\"a\")\n        fcntl.flock(self.lock,fcntl.LOCK_EX|fcntl.LOCK_NB)\n        raw=subprocess.check_output([\"nvidia-smi\",\"--query-gpu=uuid,memory.used,memory.total,name,utilization.gpu\",\n                    \"--format=csv,noheader,nounits\"],text=True,timeout=30)\n        cards=[dict(uuid=r[0].strip(),used_mib=float(r[1]),total_mib=float(r[2]),name=r[3].strip(),utilization_percent=float(r[4]))\n               for r in csv.reader(raw.splitlines()) if len(r)>=5]\n        matches=[c for c in cards if c[\"uuid\"]==gpu_uuid]\n        if len(matches)!=1:raise RuntimeError(\"Scheduled physical GPU UUID is absent\")\n        raw=subprocess.check_output([\"nvidia-smi\",\"--query-compute-apps=gpu_uuid,pid\",\n                    \"--format=csv,noheader,nounits\"],text=True,timeout=30)\n        contexts=[dict(gpu_uuid=r[0].strip(),pid=r[1].strip()) for r in csv.reader(raw.splitlines()) if len(r)>=2]\n        card=gpu_admission(matches[0],contexts,gpu_uuid,minimum_free_mib)\n        self.started_epoch=time.time();self.started_monotonic=time.monotonic()\n        self.folder=self.root.parent/\"benchmark_B1_20261119\"/\"gpu_runtime\"/(\"job_\"+self.job)\n        self.protect(self.root,64*1024**2,self.snapshot,own_concurrent_bytes=40*GIB)\n        self.folder.mkdir(parents=True,exist_ok=False);temporary=self.folder/\"tmp\";temporary.mkdir()\n        for key in (\"TMPDIR\",\"TMP\",\"TEMP\",\"XDG_CACHE_HOME\",\"MPLCONFIGDIR\",\"CUDA_CACHE_PATH\"):\n            os.environ[key]=str(temporary/key.lower())\n            Path(os.environ[key]).mkdir()\n        os.environ[\"CUDA_VISIBLE_DEVICES\"]=gpu_uuid\n        self.record=dict(status=\"ADMITTED_FOR_AUTHORIZED_NEURAL_GPU_JOB\",job=self.job,node=self.node,\n            gpu_uuid=gpu_uuid,learner=learner,pid=os.getpid(),uid=os.getuid(),\n            cpus=int(os.environ[\"SLURM_CPUS_PER_TASK\"]),started_epoch=self.started_epoch,\n            initial_GPU=card,existing_compute_contexts=[],shared_GPU_lock=str(LOCK_ROOT/(gpu_uuid+\".lock\")),\n            Slurm_GPU_GRES_requested=False,Slurm_exclusive_requested=False,\n            GPU_used_by_recipe9M=False,root_tmp_reserve=self.local_capacity(),\n            output_filesystem=str(self.root),quota_snapshot=str(self.snapshot),\n            model_reserve_bytes=MODEL_RESERVE,own_concurrent_peak_bytes=40*GIB,\n            temporary_outputs=str(temporary),scientific_hyperparameters_or_labels_changed=False)\n        self.manifest=self.folder/\"admission.json\"\n        self.manifest.write_text(json.dumps(self.record,indent=2)+\"\\n\")\n        print(\"DOWNSTREAM_GPU_ADMITTED\",self.job,self.node,self.gpu_uuid,learner,flush=True)\n\n    def local_capacity(self):\n        root_stat=os.statvfs(\"/\")\n        root_device=os.stat(\"/\").st_dev\n        result={\"/\":root_capacity(root_stat,16*1024**2)}\n        result[\"/tmp\"]=root_capacity(os.statvfs(\"/tmp\"),16*1024**2,os.stat(\"/tmp\").st_dev==root_device)\n        return result\n\n    def quantum_future(self):\n        forecast=0\n        for folder in (self.root/\"labels/Pprime/shared_v1\",\n                       self.root/\"directive19/uniform_Sprime/labels/Pprime/shared_v1\"):\n            access_path=folder/\"access.json\"\n            if not access_path.is_file():\n                raise RuntimeError(\"Native concurrent quantum-write capacity declaration is missing\")\n            access=json.loads(access_path.read_text())\n            if access.get(\"immutable\") and access.get(\"cross_node_read_allowed\"):continue\n            existing=sum(p.stat().st_size for p in folder.glob(\"*.sqlite\"))\n            forecast+=max(0,80000000000-existing)\n        return forecast\n\n    def protect(self, root, needed, snapshot, own_concurrent_bytes=40*GIB):\n        if Path(root).resolve()!=self.root.resolve():\n            raise ValueError(\"GPU model output guard was called for an undeclared filesystem root\")\n        self.local_capacity()\n        observation=json.loads(Path(snapshot).read_text())\n        remaining=quota_observation(observation,os.getuid(),time.time())\n        guard(self.root,needed+self.quantum_future(),remaining,time.monotonic(),\n              MODEL_RESERVE+max(40*GIB,own_concurrent_bytes))\n\n    def finish(self, status, error=None, torch_module=None):\n        self.protect(self.root,1024**2,self.snapshot,own_concurrent_bytes=40*GIB)\n        values=dict(self.record,status=status,finished_epoch=time.time(),\n            native_GPU_owned_seconds=time.monotonic()-self.started_monotonic,error=error)\n        if torch_module is not None:\n            values[\"torch_version\"]=torch_module.__version__\n            values[\"CUDA_runtime_version\"]=torch_module.version.cuda\n            values[\"actual_CUDA_context_initialized\"]=torch_module.cuda.is_initialized()\n            values[\"maximum_CUDA_allocated_bytes\"]=torch_module.cuda.max_memory_allocated() if torch_module.cuda.is_initialized() else None\n        (self.folder/\"finished.json\").write_text(json.dumps(values,indent=2)+\"\\n\")\n        print(\"DOWNSTREAM_GPU_NATIVE_BODY_CLOSED\",self.job,status,values[\"native_GPU_owned_seconds\"],flush=True)\n        # Keep the lock descriptor alive until the native process exits.\n\ndef prepare_neural_source(source, learner):\n    \"\"\"Route the actual neural call to GPU and defer bootstrap/report statistics.\"\"\"\n    if learner not in (\"Chemprop-v2\",\"TabPFN\"):\n        raise ValueError(\"Only the explicitly authorized neural GPU learners may use this adapter\")\n    class Adapter(ast.NodeTransformer):\n        def visit_ImportFrom(self,node):\n            if node.module==\"workflows.benchmark_data.admission\":\n                other=[a for a in node.names if a.name!=\"protect\"]\n                nodes=[]\n                if other:nodes.append(ast.ImportFrom(module=node.module,names=other,level=node.level))\n                if any(a.name==\"protect\" for a in node.names):\n                    nodes.append(ast.Assign(targets=[ast.Name(id=\"protect\",ctx=ast.Store())],\n                        value=ast.Attribute(value=ast.Name(id=\"_gpu_runtime\",ctx=ast.Load()),attr=\"protect\",ctx=ast.Load())))\n                return nodes\n            return node\n        def visit_FunctionDef(self,node):\n            if node.name in (\"score\",\"mean_reference_metrics\"):\n                replacement=ast.parse(\"def \"+node.name+\"(*args, **kwargs):\\n\"\n                    \"    return dict(metric_status='PENDING_CPU_STATISTICS', n_test_rows=len(args[0]), bootstrap_draws=0, CPU_statistics_deferred=True)\\n\").body[0]\n                return ast.copy_location(replacement,node)\n            return self.generic_visit(node)\n        def visit_If(self,node):\n            if any(isinstance(x,ast.Call) and isinstance(x.func,ast.Attribute)\n                   and x.func.attr==\"TextTestRunner\" for x in ast.walk(node.test)):\n                return ast.copy_location(ast.Pass(),node)\n            return self.generic_visit(node)\n        def visit_Call(self,node):\n            node=self.generic_visit(node)\n            for keyword in node.keywords:\n                if isinstance(keyword.value,ast.Constant) and keyword.value.value==\"cpu\":\n                    if learner==\"Chemprop-v2\" and keyword.arg==\"accelerator\":keyword.value=ast.Constant(value=\"gpu\")\n                    if learner==\"TabPFN\" and keyword.arg==\"device\":keyword.value=ast.Constant(value=\"cuda\")\n            if (learner==\"Chemprop-v2\" and isinstance(node.func,ast.Attribute) and node.func.attr==\"Trainer\"\n                    and not any(k.arg==\"precision\" for k in node.keywords)):\n                node.keywords.append(ast.keyword(arg=\"precision\",value=ast.Constant(value=\"32-true\")))\n            return node\n        def visit_Assign(self,node):\n            node=self.generic_visit(node)\n            if any(isinstance(t,ast.Name) and t.id in (\"official_score\",\"official_value\") for t in node.targets):\n                node.value=ast.Constant(value=None)\n            return node\n    tree=Adapter().visit(ast.parse(source));ast.fix_missing_locations(tree)\n    answer=ast.unparse(tree)+\"\\n\"\n    # Validate the generated program only; no scientific payload is executed here.\n    compile(answer,\"authorized_downstream_neural_GPU_program\",\"exec\")\n    return answer\n",module.__name__,'exec'),module.__dict__)
out=root.parent/'benchmark_B1_20261119/gpu_programs'/('job_'+os.environ['SLURM_JOB_ID']+'_step_'+os.environ['SLURM_STEP_ID']);out.mkdir(parents=True)
sources={"pKa_Chemprop":["Chemprop-v2","\nimport csv,json,math,os,time,unittest,importlib.metadata,traceback,gc\nfrom pathlib import Path\nfrom collections import defaultdict,Counter\nimport numpy as np\nimport pyarrow as pa\nimport pyarrow.parquet as pq\nimport torch\nfrom lightning import pytorch as pl\nfrom lightning.pytorch.callbacks import Callback,ModelCheckpoint\nfrom chemprop import data,featurizers,nn,models\nfrom workflows.benchmark_data.admission import protect\ntorch.set_num_threads(4);torch.set_num_interop_threads(1)\nSEED=20261025\ndef score(y,prediction,train_mean,groups,draws=1000):\n    y=np.asarray(y,float);prediction=np.asarray(prediction,float);groups=np.asarray(groups)\n    if y.ndim!=1 or y.shape!=prediction.shape or y.shape!=groups.shape or not len(y):raise ValueError('Unaligned evaluation rows')\n    if not np.isfinite(y).all() or not np.isfinite(prediction).all() or not math.isfinite(train_mean):raise ValueError('Nonfinite labels or predictions')\n    unique,inverse=np.unique(groups,return_inverse=True)\n    error=np.abs(y-prediction);reference=np.abs(y-train_mean)\n    numerator=np.bincount(inverse,weights=error,minlength=len(unique))\n    denominator=np.bincount(inverse,weights=reference,minlength=len(unique))\n    total=float(denominator.sum())\n    result={'MAE':float(error.mean()),'RAE':None,'RAE_CI95_low':None,'RAE_CI95_high':None,'n_test_rows':len(y),'n_test_molecules':len(unique),'bootstrap_draws':draws,'undefined_bootstrap_draws':0}\n    if total<=0:return dict(result,metric_status='ZERO_TRAIN_MEAN_REFERENCE_ERROR')\n    result['RAE']=float(numerator.sum()/total)\n    rng=np.random.default_rng(SEED);values=[]\n    for _ in range(draws):\n        sample=rng.integers(0,len(unique),size=len(unique));divisor=float(denominator[sample].sum())\n        if divisor<=0:result['undefined_bootstrap_draws']+=1\n        else:values.append(float(numerator[sample].sum()/divisor))\n    if result['undefined_bootstrap_draws']:return dict(result,metric_status='UNDEFINED_BOOTSTRAP_REFERENCE_DRAWS')\n    result['RAE_CI95_low'],result['RAE_CI95_high']=map(float,np.quantile(values,[.025,.975]))\n    return dict(result,metric_status='OK')\nclass StatisticTests(unittest.TestCase):\n    def test_atom_or_repeat_rows_cluster_by_molecule(self):\n        y=np.tile([0.,2.],40);prediction=y+.2;groups=np.repeat(np.arange(40),2)\n        result=score(y,prediction,1.,groups)\n        self.assertEqual(result['n_test_molecules'],40)\n        self.assertAlmostEqual(result['RAE'],.2)\n        self.assertAlmostEqual(result['RAE_CI95_low'],.2)\n        self.assertAlmostEqual(result['RAE_CI95_high'],.2)\n    def test_zero_reference_is_not_fabricated(self):\n        result=score([1.,1.],[1.1,1.2],1.,['a','b'])\n        self.assertIsNone(result['RAE'])\n        self.assertEqual(result['metric_status'],'ZERO_TRAIN_MEAN_REFERENCE_ERROR')\n    def test_missing_prediction_does_not_change_population(self):\n        with self.assertRaises(ValueError):score([1.],[float('nan')],0.,['a'])\n    def test_training_mean_is_used_without_test_refitting(self):\n        result=score([2.,4.],[1.,3.],0.,['a','b'])\n        self.assertAlmostEqual(result['RAE'],1/3)\nsuite=unittest.defaultTestLoader.loadTestsFromTestCase(StatisticTests)\nif not unittest.TextTestRunner(verbosity=2).run(suite).wasSuccessful():raise SystemExit(1)\n\ndef target_value(group,raw):\n    try:value=float(raw['y' if group=='MoleculeACE' else 'value'])\n    except (TypeError,ValueError,KeyError):return None\n    return value if math.isfinite(value) else None\ndef eligible(row):return bool(row['retained'] and row['domain_eligible'])\n\nentry=json.loads(Path('configs/benchmark_data/B0.DELIVERY.json').read_text())\nroot=Path(entry['data_root']);b1=root.parent/'benchmark_B1_20261119'\nquota=Path('/share/home/zixiao/descriptor_analysis/runs/data_v1_20261025/control/benchmark_B0_quota_20261119.json')\ndef safe():protect(root,2*1024**3,quota,own_concurrent_bytes=24*1024**3)\nsafe()\nfeatures=b1/'B1_pKa_features/job_4537022'\ncontract=json.loads((features/'manifest.json').read_text())\nproof=json.loads(Path(contract['scope_proof']).read_text())\nassert proof['deferred_registry_full_inventory_verified']\nout=b1/'B1_Chemprop'/('job_'+os.environ['SLURM_JOB_ID']);out.mkdir(parents=True,exist_ok=False)\nos.environ['TMPDIR']=str(out/'tmp');(out/'tmp').mkdir();import tempfile;tempfile.tempdir=os.environ['TMPDIR']\nprotocol={'authority':'USER_DIRECTIVE_20261119 and BENCHMARK_PLAN 2.2/4.3','model':'Chemprop v2 graph only','chemprop_version':importlib.metadata.version('chemprop'),'seed':SEED,'epochs':50,'checkpoint_selection':'Fixed final epoch; no validation or TEST selection','official_TRAIN_usage':'All eligible official TRAIN rows for primary fit, all processable official TRAIN rows for full-population diagnostic','hyperparameters':'Official defaults: BondMessagePassing d_h=300 depth=3, MeanAggregation, default one-task FFN, batch_size=64, warmup=2epochs, init_lr=1e-4 max_lr=1e-3 final_lr=1e-4','target_normalization':'Regression fit on TRAIN only; inverse transformed in prediction. Binary classifier predicts class-1 probability','reference_predictor':'Arithmetic mean/prevalence of original unscaled labels for the fit TRAIN population','full_filter_impact':'Separate full-TRAIN fit; evaluate full/retained/excluded official TEST','training_checkpoints':'One last.ckpt per fit population, at every completed epoch','default_seed_count':1,'no_PRETRAINING':True}\n(out/'protocol_before_fitting.json').write_text(json.dumps(protocol,indent=2)+'\\n')\nclass DiskGuard(Callback):\n    def on_train_epoch_start(self,trainer,module):safe()\n    def on_train_epoch_end(self,trainer,module):\n        print('B1_CHEMPROP_EPOCH',self.task,self.population,trainer.current_epoch+1,flush=True)\ndef train_predict(train_rows,test_rows,classifier,checkpoint_dir,task,population):\n    pl.seed_everything(SEED,workers=True,verbose=False)\n    train_points=[data.MoleculeDatapoint.from_smi(r['feature_smiles'],[r['y']]) for r in train_rows]\n    test_points=[data.MoleculeDatapoint.from_smi(r['feature_smiles'],[r['y']]) for r in test_rows]\n    featurizer=featurizers.SimpleMoleculeMolGraphFeaturizer()\n    training=data.MoleculeDataset(train_points,featurizer);testing=data.MoleculeDataset(test_points,featurizer)\n    training.cache=True;testing.cache=True\n    if classifier:\n        predictor=nn.BinaryClassificationFFN()\n        target_scaler=None\n    else:\n        target_scaler=training.normalize_targets()\n        predictor=nn.RegressionFFN(output_transform=nn.UnscaleTransform.from_standard_scaler(target_scaler))\n    mp=nn.BondMessagePassing();mpnn=models.MPNN(mp,nn.MeanAggregation(),predictor)\n    loader=data.build_dataloader(training,batch_size=64,num_workers=0,seed=SEED,shuffle=True)\n    testloader=data.build_dataloader(testing,batch_size=64,num_workers=0,shuffle=False,drop_last=False)\n    guard=DiskGuard();guard.task=task;guard.population=population\n    checkpoint=ModelCheckpoint(dirpath=checkpoint_dir,save_last=True,save_top_k=0,every_n_epochs=1,enable_version_counter=False)\n    trainer=pl.Trainer(accelerator='cpu',devices=1,max_epochs=50,logger=False,enable_checkpointing=True,callbacks=[guard,checkpoint],enable_progress_bar=False,enable_model_summary=False,num_sanity_val_steps=0,limit_val_batches=0,default_root_dir=checkpoint_dir,log_every_n_steps=50)\n    trainer.fit(mpnn,loader)\n    with torch.inference_mode():\n        prediction=torch.cat(trainer.predict(mpnn,testloader),dim=0).reshape(-1).detach().cpu().numpy().astype(float)\n    if len(prediction)!=len(test_rows) or not np.isfinite(prediction).all():raise ValueError('Unaligned or nonfinite Chemprop predictions')\n    fitmeta={'completed_epochs':trainer.current_epoch,'model_hyperparameters':str(mpnn.hparams),'target_scaler_mean':target_scaler.mean_.tolist() if target_scaler is not None else None,'target_scaler_scale':target_scaler.scale_.tolist() if target_scaler is not None else None,'final_checkpoint':str(checkpoint_dir/'last.ckpt')}\n    del trainer,mpnn,training,testing,loader,testloader\n    gc.collect()\n    return prediction,fitmeta\nclass TrainingBindingTests(unittest.TestCase):\n    def test_training_scale_excludes_test_labels(self):\n        points=[data.MoleculeDatapoint.from_smi('CCO',[value]) for value in (0.,2.)]\n        ds=data.MoleculeDataset(points,featurizers.SimpleMoleculeMolGraphFeaturizer())\n        scaler=ds.normalize_targets()\n        self.assertAlmostEqual(float(scaler.mean_[0]),1.)\n        self.assertAlmostEqual(float(scaler.scale_[0]),1.)\n    def test_scored_targets_keep_original_units(self):\n        rows=[{'original_fields_json':json.dumps({'y':'4.2'})}]\n        self.assertEqual(target_value('MoleculeACE',json.loads(rows[0]['original_fields_json'])),4.2)\nbinding_suite=unittest.defaultTestLoader.loadTestsFromTestCase(TrainingBindingTests)\nif not unittest.TextTestRunner(verbosity=2).run(binding_suite).wasSuccessful():raise SystemExit(1)\nprediction_schema=pa.schema([('dataset',pa.string()),('task',pa.string()),('model',pa.string()),('fit_population',pa.string()),('record_id',pa.string()),('full_inchikey',pa.string()),('y_true',pa.float64()),('prediction',pa.float64()),('training_mean',pa.float64()),('retained',pa.bool_()),('domain_eligible',pa.bool_())])\nresults=[];failures=[];coverage_report=[];task_index=0\n\ngroup='pKahub';tasks=defaultdict(list);coverage=defaultdict(Counter)\nfor batch in pq.ParquetFile(contract['records']).iter_batches(batch_size=1024):\n    for row in batch.to_pylist():\n        task=row['task'];counts=coverage[task];split=row['official_split'];counts[split+'_source_rows']+=1\n        if row['ecfp4_2048_packed'] is None or not row['full_inchikey']:counts['unresolved_graph_or_identity']+=1;continue\n        tasks[task].append(dict(row,split=split));counts[split+'_processable']+=1\nfor group in ('pKahub',):\n    for task in sorted(tasks):\n        task_index+=1;taskdir=out/('task_%03d'%task